# The default and cap every paginated list endpoint applies. A page this size is
# small enough that an unindexed sort would still have been usable during
# development, which is exactly why the cap matters once the table is real: a
# caller can ask for more per page, never for the whole table in one response.
DEFAULT_PAGE_LIMIT = 50
MAX_PAGE_LIMIT = 200


def not_found(entity: str) -> HTTPException:
    return HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=f"{entity} not found")


def conflict(detail: str) -> HTTPException:
    return HTTPException(status_code=status.HTTP_409_CONFLICT, detail=detail)


def get_work_item(db: Session, item_id: UUID) -> WorkItem:
    item = db.scalar(select(WorkItem).options(selectinload(WorkItem.evidence)).where(WorkItem.id == item_id))
    if item is None:
        raise not_found("Work item")
    return item


def list_work_items(db: Session, status_filter: WorkStatus | None, source_kind: str | None, assigned_agent: str | None,
                    limit: int = DEFAULT_PAGE_LIMIT, offset: int = 0) -> tuple[list[WorkItem], int]:
    conditions = []
    if status_filter:
        conditions.append(WorkItem.status == status_filter)
    if source_kind:
        conditions.append(WorkItem.source_kind == source_kind)
    if assigned_agent:
        conditions.append(WorkItem.assigned_agent == assigned_agent)
    total = db.scalar(select(func.count()).select_from(WorkItem).where(*conditions))
    query = (select(WorkItem).options(selectinload(WorkItem.evidence)).where(*conditions)
             .order_by(WorkItem.updated_at.desc()).limit(limit).offset(offset))
    return list(db.scalars(query)), total


def create_work_item(db: Session, payload: WorkItemCreate) -> WorkItem:
    data = payload.model_dump(exclude={"evidence"}, mode="json")
    data["source_url"] = str(data["source_url"]) if data.get("source_url") else None
    item = WorkItem(**data)
    for evidence in payload.evidence:
        item.evidence.append(WorkEvidence(**evidence.model_dump(exclude={"observed_at"}), observed_at=evidence.observed_at))
    db.add(item)
    try:
        db.commit()
    except IntegrityError:
        db.rollback()

def encrypt_text(value: str) -> str:
    nonce = os.urandom(NONCE_BYTES)
    sealed = nonce + _cipher().encrypt(nonce, value.encode(), EXCERPT_AAD)
    return CIPHERTEXT_PREFIX + base64.urlsafe_b64encode(sealed).decode()


def decrypt_text(stored: str) -> str:
    if not stored.startswith(CIPHERTEXT_PREFIX):
        raise FieldEncryptionError("stored message content is not encrypted; run the Alembic migrations")
    try:
        raw = base64.urlsafe_b64decode(stored[len(CIPHERTEXT_PREFIX):].encode())
        return _cipher().decrypt(raw[:NONCE_BYTES], raw[NONCE_BYTES:], EXCERPT_AAD).decode()
